import type { ClassValue } from "clsx"
import { CheckIcon } from "@octanejs/lucide"
import type { ComponentProps, OctaneNode } from "octane"
import type { VariantProps } from "class-variance-authority"

import { Questionnaire as QuestionnairePrimitive } from "@/components/primitives/questionnaire/index.ts"
import { buttonVariants } from "@/components/ui/button.tsrx"

import { cn } from "@/lib/utils"

// Octane takes `class`; `className` is what base-ui hands to an element
// passed as `render={…}`, so components fold in both.
type ClassProps = { class?: ClassValue; className?: string }

type StyledProps<P> = Omit<P, "className"> & ClassProps

type ButtonVariantProps = Pick<
  VariantProps<typeof buttonVariants>,
  "size" | "variant"
>

function Questionnaire({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Root>>) @{
  <QuestionnairePrimitive.Root
    data-slot="questionnaire"
    className={cn("flex w-full min-w-0 flex-col gap-6", className, klass)}
    {...props}
  />
}

function QuestionnaireProgress({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Progress>>) @{
  <QuestionnairePrimitive.Progress
    data-slot="questionnaire-progress"
    className={cn(
      "min-h-[1lh] w-fit min-w-[14ch] text-xs font-base text-foreground tabular-nums",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnaireItem({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Item>>) @{
  <QuestionnairePrimitive.Item
    data-slot="questionnaire-item"
    className={cn(
      "flex min-w-0 flex-col gap-5 border-0 p-0 outline-none",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnaireTitle({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Title>>) @{
  <QuestionnairePrimitive.Title
    data-slot="questionnaire-title"
    className={cn(
      "text-base leading-snug font-heading text-foreground text-pretty [&:not(:has(~[data-slot=questionnaire-description]))]:mb-4",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnaireDescription({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Description>>) @{
  <QuestionnairePrimitive.Description
    data-slot="questionnaire-description"
    className={cn(
      "text-sm font-base text-pretty text-foreground",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnaireChoices({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Choices>>) @{
  <QuestionnairePrimitive.Choices
    data-slot="questionnaire-choices"
    className={cn(
      "group/questionnaire-choices grid min-w-0 gap-3",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnaireChoice({
  children,
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Choice>>) @{
  <QuestionnairePrimitive.Choice
    data-slot="questionnaire-choice"
    className={cn(
      "group/questionnaire-choice relative flex min-h-11 cursor-pointer items-start gap-3 rounded-base border-2 border-border bg-secondary-background px-4 py-3 text-start text-sm font-base text-foreground transition-colors outline-none select-none has-[>input:focus-visible]:ring-2 has-[>input:focus-visible]:ring-black has-[>input:focus-visible]:ring-offset-2 data-checked:bg-background",
      "data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:opacity-50",
      className,
      klass,
    )}
    {...props}
  >
    <QuestionnairePrimitive.ChoiceInput
      data-slot="questionnaire-choice-input"
      className="absolute inset-0 z-10 size-full cursor-pointer opacity-0"
    />
    <span
      aria-hidden="true"
      data-slot="questionnaire-choice-indicator"
      class="pointer-events-none relative flex size-4 shrink-0 translate-y-[--spacing(0.45)] items-center justify-center rounded-base border-2 border-border bg-secondary-background text-main-foreground group-has-data-[slot=questionnaire-choice-description]/questionnaire-choice:translate-y-0.5 group-data-[type=radio]/questionnaire-choice:rounded-full group-data-checked/questionnaire-choice:bg-main group-data-checked/questionnaire-choice:group-data-[type=radio]/questionnaire-choice:bg-transparent"
    >
      <span
        data-slot="questionnaire-choice-indicator-dot"
        class="hidden size-2 rounded-full bg-current group-data-[type=checkbox]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block"
      />
      <CheckIcon
        data-slot="questionnaire-choice-indicator-check"
        class="hidden size-3.5 group-data-[type=radio]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block"
      />
    </span>
    <QuestionnairePrimitive.ChoiceLabel
      data-slot="questionnaire-choice-label"
      className="flex min-w-0 flex-1 flex-col gap-0.5 leading-snug"
    >
      {children}
    </QuestionnairePrimitive.ChoiceLabel>
    <QuestionnairePrimitive.ChoiceShortcut
      data-slot="questionnaire-choice-shortcut"
      className="pointer-events-none ms-auto hidden size-5 shrink-0 items-center justify-center rounded-full border-2 border-border bg-secondary-background text-xs leading-none font-base text-foreground group-data-checked/questionnaire-choice:bg-background group-data-[shortcut]/questionnaire-choice:inline-flex"
    />
  </QuestionnairePrimitive.Choice>
}

function QuestionnaireChoiceDescription({
  class: klass,
  className,
  ...props
}: Record<string, any> & ClassProps & { children?: OctaneNode }) @{
  <span
    data-slot="questionnaire-choice-description"
    class={cn("text-foreground", className, klass)}
    {...props}
  />
}

function QuestionnaireInput({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Input>>) @{
  <div
    data-slot="questionnaire-input-wrapper"
    class="group/questionnaire-input relative w-full min-w-0"
  >
    <QuestionnairePrimitive.Input
      data-slot="questionnaire-input"
      className={cn(
        "flex h-10 min-h-10 w-full min-w-0 rounded-base border-2 border-border bg-secondary-background px-3 py-2 text-base font-base text-foreground focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-black focus-visible:ring-offset-2 disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 sm:min-h-0 md:text-sm",
        "selection:bg-main selection:text-main-foreground placeholder:text-foreground/50",
        className,
        klass,
      )}
      {...props}
    />
  </div>
}

function QuestionnaireError({
  class: klass,
  className,
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Error>>) @{
  <QuestionnairePrimitive.Error
    data-slot="questionnaire-error"
    className={cn("mt-2 text-sm font-base text-red-500", className, klass)}
    {...props}
  />
}

function QuestionnaireActions({
  class: klass,
  className,
  ...props
}: Record<string, any> & ClassProps & { children?: OctaneNode }) @{
  <div
    data-slot="questionnaire-actions"
    class={cn(
      "grid min-h-11 w-full grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-2 sm:min-h-8",
      className,
      klass,
    )}
    {...props}
  />
}

function QuestionnairePrevious({
  children,
  class: klass,
  className,
  size = "sm",
  variant = "neutral",
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Previous>> &
  ButtonVariantProps) @{
  <QuestionnairePrimitive.Previous
    data-slot="questionnaire-previous"
    data-size={size}
    data-variant={variant}
    className={cn(
      buttonVariants({ size, variant }),
      "col-start-1 row-start-1 min-h-11 justify-self-start sm:min-h-0",
      className,
      klass,
    )}
    {...props}
  >
    {children ?? "Previous"}
  </QuestionnairePrimitive.Previous>
}

function QuestionnaireSkip({
  children,
  class: klass,
  className,
  size = "sm",
  variant = "neutral",
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Skip>> &
  ButtonVariantProps) @{
  <QuestionnairePrimitive.Skip
    data-slot="questionnaire-skip"
    data-size={size}
    data-variant={variant}
    className={cn(
      buttonVariants({ size, variant }),
      "col-start-2 row-start-1 min-h-11 justify-self-end sm:min-h-0",
      className,
      klass,
    )}
    {...props}
  >
    {children ?? "Skip"}
  </QuestionnairePrimitive.Skip>
}

function QuestionnaireNext({
  children,
  class: klass,
  className,
  size = "sm",
  variant = "default",
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Next>> &
  ButtonVariantProps) @{
  <QuestionnairePrimitive.Next
    data-slot="questionnaire-next"
    data-size={size}
    data-variant={variant}
    className={cn(
      buttonVariants({ size, variant }),
      "col-start-3 row-start-1 min-h-11 justify-self-end sm:min-h-0",
      className,
      klass,
    )}
    {...props}
  >
    {children ?? "Next"}
  </QuestionnairePrimitive.Next>
}

function QuestionnaireSubmit({
  children,
  class: klass,
  className,
  size = "sm",
  variant = "default",
  ...props
}: StyledProps<ComponentProps<typeof QuestionnairePrimitive.Submit>> &
  ButtonVariantProps) @{
  <QuestionnairePrimitive.Submit
    data-slot="questionnaire-submit"
    data-size={size}
    data-variant={variant}
    className={cn(
      buttonVariants({ size, variant }),
      "col-start-3 row-start-1 min-h-11 justify-self-end sm:min-h-0",
      className,
      klass,
    )}
    {...props}
  >
    {children ?? "Submit"}
  </QuestionnairePrimitive.Submit>
}

export {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireProgress,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
}

/**
 * Octane questionnaire primitive (collection).
 * Derived from shadcn-ui/ui@295a1f114a138f23b5dfee0e0c6812394dfeb90c (questionnaire).
 * License: MIT, (c) 2023 shadcn — see ../LICENSE.upstream.md.
 * Framework-neutral logic.
 */
import type {
  ItemRegistration,
  QuestionnaireItemDefinition,
  QuestionnaireShortcutMode,
} from "./types"
import { getShortcutKeys } from "./utils"

type QuestionnaireCollection = {
  enabledItems: readonly QuestionnaireItemDefinition[]
  itemByName: ReadonlyMap<string, QuestionnaireItemDefinition>
  items: readonly QuestionnaireItemDefinition[]
}

function createQuestionnaireCollection(
  items: readonly QuestionnaireItemDefinition[] | undefined,
): QuestionnaireCollection | null {
  if (items === undefined) {
    return null
  }

  return {
    enabledItems: items.filter((item) => !item.disabled),
    itemByName: new Map(items.map((item) => [item.name, item])),
    items,
  }
}

function getInitialItemName(
  collection: QuestionnaireCollection | null,
  defaultItem: string | undefined,
) {
  if (!collection) {
    return defaultItem ?? null
  }

  const defaultDefinition = defaultItem
    ? collection.itemByName.get(defaultItem)
    : undefined

  if (defaultDefinition && !defaultDefinition.disabled) {
    return defaultDefinition.name
  }

  return collection.enabledItems[0]?.name ?? null
}

function getShortcutByChoiceValue(
  item: QuestionnaireItemDefinition | undefined,
  shortcuts: QuestionnaireShortcutMode | null,
) {
  const shortcutByChoiceValue = new Map<string, string>()

  if (!item || !shortcuts) {
    return shortcutByChoiceValue
  }

  const keys = getShortcutKeys(shortcuts)
  let shortcutIndex = 0

  for (const choice of item.choices ?? []) {
    if (choice.disabled) {
      continue
    }

    const shortcut = keys[shortcutIndex]

    if (!shortcut) {
      break
    }

    shortcutByChoiceValue.set(choice.value, shortcut)
    shortcutIndex += 1
  }

  return shortcutByChoiceValue
}

function getCollectionDefinitionWarnings(
  collection: QuestionnaireCollection,
  defaultItem: string | undefined,
) {
  const warnings: string[] = []
  const itemNames = new Set<string>()

  for (const item of collection.items) {
    if (itemNames.has(item.name)) {
      warnings.push(`Item name "${item.name}" is defined more than once.`)
    }

    itemNames.add(item.name)

    const choiceValues = new Set<string>()

    for (const choice of item.choices ?? []) {
      if (choiceValues.has(choice.value)) {
        warnings.push(
          `Choice value "${choice.value}" is defined more than once in item "${item.name}".`,
        )
      }

      choiceValues.add(choice.value)
    }
  }

  if (defaultItem) {
    const defaultDefinition = collection.itemByName.get(defaultItem)

    if (!defaultDefinition || defaultDefinition.disabled) {
      warnings.push(
        `defaultItem "${defaultItem}" does not identify an enabled item. The first enabled item will be used instead.`,
      )
    }
  }

  return warnings
}

function getCollectionRegistrationWarnings(
  collection: QuestionnaireCollection,
  registrations: readonly ItemRegistration[],
  shortcuts: QuestionnaireShortcutMode | null,
) {
  const warnings: string[] = []
  const registrationByName = new Map(
    registrations.map((registration) => [registration.name, registration]),
  )

  for (const definition of collection.items) {
    const registration = registrationByName.get(definition.name)

    if (!registration) {
      if (!definition.disabled) {
        warnings.push(
          `Item "${definition.name}" is defined but has no rendered Questionnaire.Item.`,
        )
      }

      continue
    }

    if (registration.disabled !== Boolean(definition.disabled)) {
      warnings.push(
        `Item "${definition.name}" has different disabled values in Root.items and Questionnaire.Item.`,
      )
    }

    if (registration.required !== Boolean(definition.required)) {
      warnings.push(
        `Item "${definition.name}" has different required values in Root.items and Questionnaire.Item.`,
      )
    }

    const definedChoices = definition.choices ?? []
    const definedChoiceByValue = new Map(
      definedChoices.map((choice) => [choice.value, choice]),
    )
    const registeredChoiceByValue = new Map(
      registration.choices.map((choice) => [choice.value, choice]),
    )

    for (const choice of definedChoices) {
      const registeredChoice = registeredChoiceByValue.get(choice.value)

      if (!registeredChoice) {
        warnings.push(
          `Choice "${choice.value}" is defined for item "${definition.name}" but has no rendered Questionnaire.Choice.`,
        )
        continue
      }

      if (registeredChoice.disabled !== Boolean(choice.disabled)) {
        warnings.push(
          `Choice "${choice.value}" in item "${definition.name}" has different disabled values in Root.items and Questionnaire.Choice.`,
        )
      }
    }

    if (shortcuts) {
      for (const choice of registration.choices) {
        if (!definedChoiceByValue.has(choice.value)) {
          warnings.push(
            `Rendered choice "${choice.value}" in item "${definition.name}" is missing from Root.items and will not receive a shortcut.`,
          )
        }
      }

      const definedOrder = definedChoices
        .filter((choice) => !choice.disabled)
        .map((choice) => choice.value)
      const registeredOrder = registration.choices
        .filter((choice) => !choice.disabled)
        .map((choice) => choice.value)

      const sameChoices =
        definedOrder.length > 0 &&
        definedOrder.length === registeredOrder.length &&
        definedOrder.every((choiceValue) =>
          registeredOrder.includes(choiceValue),
        )

      if (
        sameChoices &&
        definedOrder.some(
          (choiceValue, index) => choiceValue !== registeredOrder[index],
        )
      ) {
        warnings.push(
          `Choice order for item "${definition.name}" differs between Root.items and the rendered Questionnaire.Choice elements.`,
        )
      }
    }
  }

  for (const registration of registrations) {
    if (
      !registration.disabled &&
      !collection.itemByName.has(registration.name)
    ) {
      warnings.push(
        `Rendered item "${registration.name}" is missing from Root.items and is excluded from the questionnaire collection.`,
      )
    }
  }

  return warnings
}

export {
  createQuestionnaireCollection,
  getCollectionDefinitionWarnings,
  getCollectionRegistrationWarnings,
  getInitialItemName,
  getShortcutByChoiceValue,
}

/**
 * Octane questionnaire primitive (components).
 * Derived from shadcn-ui/ui@295a1f114a138f23b5dfee0e0c6812394dfeb90c (questionnaire).
 * License: MIT, (c) 2023 shadcn — see ../LICENSE.upstream.md.
 * Notes:
 * - Contexts render as `<Context value>` (no `.Provider`).
 * - Questionnaire.Input forwards the consumer `onInput` into the answer hook
 *   (the per-keystroke answer update runs on the native `input` event);
 *   a consumer `onChange` stays a native `change` listener.
 * - Event handler types are native DOM events.
 */
import * as Octane from "octane"
import type { OctaneNode } from "octane"

import { mergeProps, useRender } from "../use-render"
import {
  QuestionnaireChoiceContext,
  QuestionnaireContext,
  QuestionnaireItemContext,
  useQuestionnaireChoiceContext,
  useQuestionnaireContext,
  useQuestionnaireItemContext,
} from "./context"
import type {
  QuestionnaireChoiceInputProps,
  QuestionnaireChoiceLabelProps,
  QuestionnaireChoiceProps,
  QuestionnaireChoiceShortcutProps,
  QuestionnaireChoicesProps,
  QuestionnaireDescriptionProps,
  QuestionnaireErrorProps,
  QuestionnaireInputProps,
  QuestionnaireItemProps,
  QuestionnaireNavigationState,
  QuestionnaireNextProps,
  QuestionnairePreviousProps,
  QuestionnaireProgressProps,
  QuestionnaireRootProps,
  QuestionnaireSkipProps,
  QuestionnaireSubmitProps,
  QuestionnaireTitleProps,
} from "./types"
import { useQuestionnaireChoice } from "./use-questionnaire-choice"
import { useQuestionnaireInput } from "./use-questionnaire-input"
import { useQuestionnaireItem } from "./use-questionnaire-item"
import { useQuestionnaireRoot } from "./use-questionnaire-root"

function QuestionnaireRoot({
  defaultItem,
  item,
  items,
  noValidate = true,
  onItemChange,
  onReset,
  onSubmit,
  ref,
  shortcuts,
  ...props
}: QuestionnaireRootProps) @{
  const { context, rootProps, state } = useQuestionnaireRoot({
    defaultItem,
    item,
    items,
    noValidate,
    onItemChange,
    onReset,
    onSubmit,
    ref,
    shortcuts,
  })
  const element = useRender({
    defaultTagName: "form",
    props: mergeProps<"form">({ ...rootProps, noValidate }, props),
    state,
  })

  <QuestionnaireContext value={context}>{element}</QuestionnaireContext>
}

function QuestionnaireProgress({
  children,
  render,
  ...props
}: QuestionnaireProgressProps) {
  const { current, first, last, total } = useQuestionnaireContext(
    "Questionnaire.Progress",
  )
  const label = total ? `Question ${current} of ${total}` : undefined

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        "aria-label": "Questionnaire progress",
        "aria-live": "polite",
        "aria-valuemax": total || undefined,
        "aria-valuemin": total ? 1 : undefined,
        "aria-valuenow": total ? current : undefined,
        "aria-valuetext": label,
        children: children ?? label,
        role: "progressbar",
      },
      props,
    ),
    render,
    state: { current, first, last, total },
  })
}

function QuestionnaireItem({
  "aria-describedby": ariaDescribedBy,
  "aria-keyshortcuts": ariaKeyShortcuts,
  children,
  disabled = false,
  invalid = false,
  multiple = false,
  name,
  onStatusChange,
  ref,
  required = false,
  ...props
}: QuestionnaireItemProps) @{
  const { context, itemProps, state } = useQuestionnaireItem({
    "aria-describedby": ariaDescribedBy,
    "aria-keyshortcuts": ariaKeyShortcuts,
    disabled,
    invalid,
    multiple,
    name,
    onStatusChange,
    ref,
    required,
  })
  const element = useRender({
    defaultTagName: "fieldset",
    props: mergeProps<"fieldset">({ ...itemProps, children }, props),
    state,
    stateAttributesMapping: {
      active: (isActive: boolean) => ({
        "data-active": isActive ? "" : undefined,
      }),
    },
  })

  <QuestionnaireItemContext value={context}>{element}</QuestionnaireItemContext>
}

function QuestionnaireTitle({ render, ...props }: QuestionnaireTitleProps) {
  useQuestionnaireItemContext("Questionnaire.Title")

  return useRender({
    defaultTagName: "legend",
    props,
    render,
  })
}

function QuestionnaireDescription({
  id,
  render,
  ...props
}: QuestionnaireDescriptionProps) {
  const { registerDescription } = useQuestionnaireItemContext(
    "Questionnaire.Description",
  )
  const generatedId = Octane.useId()
  const descriptionId = id ?? generatedId

  Octane.useLayoutEffect(
    () => registerDescription(descriptionId),
    [descriptionId, registerDescription],
  )

  return useRender({
    defaultTagName: "p",
    props: mergeProps<"p">({ id: descriptionId }, props),
    render,
  })
}

function QuestionnaireChoices({ render, ...props }: QuestionnaireChoicesProps) {
  const { shortcuts } = useQuestionnaireItemContext("Questionnaire.Choices")

  return useRender({
    defaultTagName: "div",
    props,
    render,
    state: { shortcuts },
  })
}

function QuestionnaireChoice({
  checked,
  children,
  defaultChecked = false,
  disabled = false,
  onChange,
  render,
  value,
  ...props
}: QuestionnaireChoiceProps) @{
  const { inputProps, state } = useQuestionnaireChoice({
    checked,
    defaultChecked,
    disabled,
    onChange,
    value,
  })
  const element = useRender({
    defaultTagName: "label",
    props: mergeProps<"label">({ children }, props),
    render,
    state,
    stateAttributesMapping: {
      checked: (isChecked: boolean) => ({
        "data-checked": isChecked ? "" : undefined,
        "data-unchecked": isChecked ? undefined : "",
      }),
    },
  })

  <QuestionnaireChoiceContext value={{ inputProps, state }}>
    {element}
  </QuestionnaireChoiceContext>
}

function QuestionnaireChoiceInput({
  render,
  ...props
}: QuestionnaireChoiceInputProps) {
  const { inputProps, state } = useQuestionnaireChoiceContext(
    "Questionnaire.ChoiceInput",
  )

  return useRender({
    defaultTagName: "input",
    props: mergeProps<"input">(inputProps, props),
    render,
    state,
    stateAttributesMapping: {
      checked: (isChecked: boolean) => ({
        "data-checked": isChecked ? "" : undefined,
        "data-unchecked": isChecked ? undefined : "",
      }),
    },
  })
}

function QuestionnaireChoiceLabel({
  render,
  ...props
}: QuestionnaireChoiceLabelProps) {
  useQuestionnaireChoiceContext("Questionnaire.ChoiceLabel")

  return useRender({
    defaultTagName: "span",
    props,
    render,
  })
}

function QuestionnaireChoiceShortcut({
  children,
  render,
  ...props
}: QuestionnaireChoiceShortcutProps) {
  const { state } = useQuestionnaireChoiceContext(
    "Questionnaire.ChoiceShortcut",
  )
  const shortcutState = { shortcut: state.shortcut }

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        "aria-hidden": true,
        children: children ?? state.shortcut,
        hidden: state.shortcut === null,
      },
      props,
    ),
    render,
    state: shortcutState,
  })
}

function QuestionnaireInput({
  defaultValue,
  disabled = false,
  onInput,
  ref,
  render,
  type = "text",
  value,
  ...props
}: QuestionnaireInputProps) {
  const { inputProps, state } = useQuestionnaireInput({
    defaultValue,
    disabled,
    onInput,
    ref,
    type,
    value,
  })

  return useRender({
    defaultTagName: "input",
    props: mergeProps<"input">(inputProps, props),
    render,
    state,
    stateAttributesMapping: {
      filled: (isFilled: boolean) => ({
        "data-empty": isFilled ? undefined : "",
        "data-filled": isFilled ? "" : undefined,
      }),
    },
  })
}

function QuestionnaireError({
  children,
  id,
  render,
  ...props
}: QuestionnaireErrorProps) {
  const { invalid, registerError, required } = useQuestionnaireItemContext(
    "Questionnaire.Error",
  )
  const generatedId = Octane.useId()
  const errorId = id ?? generatedId

  Octane.useLayoutEffect(() => registerError(errorId), [errorId, registerError])

  return useRender({
    defaultTagName: "p",
    props: mergeProps<"p">(
      {
        children:
          children ??
          (required
            ? "Choose an answer to continue."
            : "Choose an answer or skip this question."),
        hidden: !invalid,
        id: errorId,
        role: invalid ? "alert" : undefined,
      },
      props,
    ),
    render,
    state: { invalid },
  })
}

function QuestionnairePrevious({
  children,
  disabled: disabledProp = false,
  onClick,
  render,
  tabIndex,
  type = "button",
  ...props
}: QuestionnairePreviousProps) {
