import { composeRefs } from "../use-render"
import { getShortcutByChoiceValue } from "./collection"
import { useQuestionnaireContext } from "./context"
import type {
  AnswerControlRegistration,
  QuestionnaireItemContextValue,
  QuestionnaireItemProps,
  QuestionnaireItemState,
  QuestionnaireItemStatus,
} from "./types"
import {
  compareAnswerOrder,
  getShortcutKeys,
  isAnswerFilled,
  isEmptyNavigableInput,
  isRadioTarget,
  isTextEntryTarget,
} from "./utils"

type UseQuestionnaireItemParameters = Pick<
  QuestionnaireItemProps,
  | "aria-describedby"
  | "aria-keyshortcuts"
  | "disabled"
  | "invalid"
  | "multiple"
  | "name"
  | "onStatusChange"
  | "ref"
  | "required"
>

function useQuestionnaireItem({
  "aria-describedby": ariaDescribedBy,
  "aria-keyshortcuts": ariaKeyShortcuts,
  disabled = false,
  invalid: externallyInvalid = false,
  multiple = false,
  name,
  onStatusChange,
  ref,
  required = false,
}: UseQuestionnaireItemParameters) {
  const {
    activeItemName,
    domVersion,
    first,
    itemDefinitionByName,
    last,
    nativeValidation,
    registerItem,
    shortcuts,
  } = useQuestionnaireContext("Questionnaire.Item")
  const [element, setElement] = Octane.useState<HTMLFieldSetElement | null>(null)
  const [answerControlRegistrations, setAnswerControlRegistrations] =
    Octane.useState<AnswerControlRegistration[]>([])
  const [validationAttempted, setValidationAttempted] = Octane.useState(false)
  const [selectedAnswerIds, setSelectedAnswerIds] = Octane.useState<string[]>([])
  const [skipped, setSkipped] = Octane.useState(false)
  const [resetVersion, setResetVersion] = Octane.useState(0)
  const [descriptionIds, setDescriptionIds] = Octane.useState<string[]>([])
  const [errorIds, setErrorIds] = Octane.useState<string[]>([])
  const defaultSelectedAnswerIdsRef = Octane.useRef<string[]>([])
  const multipleRef = Octane.useRef(multiple)
  const previousMultipleRef = Octane.useRef(multiple)
  multipleRef.current = multiple
  const active = !disabled && activeItemName === name
  const answerControls = Octane.useMemo(
    () => [...answerControlRegistrations].sort(compareAnswerOrder),
    [answerControlRegistrations, domVersion],
  )
  const answers = Octane.useMemo(
    () => answerControls.filter((registration) => !registration.disabled),
    [answerControls],
  )
  const answered = answers.some((answer) =>
    selectedAnswerIds.includes(answer.id),
  )
  const status: QuestionnaireItemStatus = skipped
    ? "skipped"
    : answered
      ? "answered"
      : "unanswered"
  const intentionallySkipped = status === "skipped" && !required
  const valid =
    disabled ||
    intentionallySkipped ||
    (!externallyInvalid && status === "answered")
  const invalid =
    !disabled &&
    !intentionallySkipped &&
    (externallyInvalid || (validationAttempted && !valid))
  const hasInputAnswer = answers.some((answer) => answer.type === "input")
  const previousStatusRef = Octane.useRef(status)
  const itemDefinition = itemDefinitionByName?.get(name)
  const shortcutByChoiceValue = Octane.useMemo(
    () =>
      itemDefinitionByName
        ? getShortcutByChoiceValue(itemDefinition, shortcuts)
        : null,
    [itemDefinition, itemDefinitionByName, shortcuts],
  )
  const shortcutByAnswerId = Octane.useMemo(() => {
    if (shortcutByChoiceValue) {
      return new Map<string, string>()
    }

    const keys = getShortcutKeys(shortcuts)
    const shortcutAnswers = answers.filter((answer) => answer.type === "choice")

    return new Map(
      shortcutAnswers
        .slice(0, keys.length)
        .map((answer, index) => [answer.id, keys[index]]),
